-- Expand authoritative PowerHub AI operational knowledge without mutating a deployed migration.
insert into public.chat_knowledge_articles
(title,primary_question,alternative_questions,answer,category,linked_route,related_operation,status,search_aliases,audience,source,version,published_at,created_by_user_id,updated_by_user_id)
select * from (values
('كيف أضيف مشتركًا؟','كيف أنشئ مشتركًا جديدًا؟','["إضافة مشترك","إنشاء مشترك","تسجيل مشترك جديد","مشترك جديد"]'::jsonb,'من قسم المشتركين اختر إضافة/إنشاء مشترك، ثم أدخل البيانات المطلوبة وفق الحقول التي تظهر لك واحفظ. بعد الإنشاء راجع بطاقة المشترك للتأكد من حالته وبياناته. لا تنشئ سجلًا مكررًا إذا كان المشترك موجودًا بالفعل؛ استخدم البحث والتعديل بدل إنشاء سجل جديد.','subscribers','المشتركين','subscriber_create','published','إضافة مشترك,إنشاء مشترك,تسجيل مشترك جديد,مشترك جديد','generator_owner','powerhub',1,now(),1,1),
('كيف أعدّل بيانات مشترك؟','كيف أعدل المشترك؟','["تعديل مشترك","تغيير بيانات المشترك","تحديث بيانات مشترك"]'::jsonb,'افتح قسم المشتركين وابحث عن المشترك المطلوب ثم اختر التعديل، غيّر الحقول المسموح بها واحفظ. راجع نتيجة الحفظ قبل مغادرة البطاقة. إذا رفض النظام التعديل، فالسبب قد يكون الصلاحية أو حالة السجل أو ارتباطه بعمليات أخرى.','subscribers','المشتركين','subscriber_update','published','تعديل مشترك,تغيير بيانات المشترك,تحديث بيانات مشترك','generator_owner','powerhub',1,now(),1,1),
('كيف أسجل قراءة العداد؟','كيف أدخل قراءة العداد؟','["تسجيل قراءة","قراءة عداد","إدخال القراءة","قراءة جديدة"]'::jsonb,'من مسار القراءات اختر تسجيل القراءة للمشترك وأدخل القراءة الحالية وفق الحقول الظاهرة، ثم احفظ. في التطبيق الميداني يقتصر المسار على تسجيل قراءة العداد؛ أما اعتماد القراءة والفوترة فيتبعان المسارات المخصصة لهما.','field_app','القراءات','meter_reading_create','published','تسجيل قراءة,قراءة عداد,إدخال القراءة,قراءة جديدة','generator_owner','powerhub',1,now(),1,1),
('كيف أعتمد القراءة؟','كيف أوافق على القراءة؟','["اعتماد قراءة","موافقة على القراءة","قبول القراءة"]'::jsonb,'بعد تسجيل القراءة راجعها من مسار القراءات المخصص للاعتماد، ثم استخدم إجراء الاعتماد المتاح حسب صلاحيتك. لا تعتمد قراءة لم تتم مراجعتها أو إذا كانت البيانات غير صحيحة.','billing','القراءات','meter_reading_approve','published','اعتماد قراءة,موافقة على القراءة,قبول القراءة','generator_owner','powerhub',1,now(),1,1),
('كيف أوثق الدفع؟','كيف أسجل دفعة أو أثبت الدفع؟','["توثيق الدفع","إثبات الدفع","تسجيل دفعة","دفع فاتورة"]'::jsonb,'من المالية والتحصيل أو الاستعلامات، افتح الفاتورة غير المسددة واختر توثيق الدفع، ثم أكمل بيانات الدفع المطلوبة. لا تعتبر العملية ناجحة إلا إذا ظهر نجاح الحفظ وتغيّرت حالة الفاتورة وفقًا لذلك.','billing','المالية والتحصيل','payment_documentation','published','توثيق الدفع,إثبات الدفع,تسجيل دفعة,دفع فاتورة','generator_owner','powerhub',1,now(),1,1),
('كيف أجدد اشتراك المنصة؟','كيف أجدد اشتراكي؟','["تجديد الاشتراك","تمديد الاشتراك","Renew subscription"]'::jsonb,'تجديد اشتراك صاحب المولد يتم من مسار المالية والتحصيل/إدارة الاشتراك وفق الصلاحيات والباقات المتاحة. راجع الباقة ومدة التجديد ثم أكمل مسار الدفع والاعتماد. لا يتم إنشاء فاتورة جديدة لمجرد القراءة الافتتاحية.','subscription','المالية والتحصيل','subscription_renew','published','تجديد الاشتراك,تمديد الاشتراك,Renew subscription','generator_owner','powerhub',1,now(),1,1),
('كيف أرسل رسالة لمشترك؟','كيف أرسل رسالة SMS لمشترك؟','["إرسال رسالة","SMS للمشترك","رسالة للمشترك"]'::jsonb,'من نظام الرسائل اختر المشترك المطلوب، ثم أنشئ الرسالة أو استخدم القالب المناسب وتحقق من رقم المستلم قبل الإرسال. يجب أن يذهب الرابط إلى رقم المستلم الصحيح، ولا تعِد الإرسال تلقائيًا عند فشل غير واضح قبل التحقق من حالة الرسالة.','messaging','المراسلات','message_send','published','إرسال رسالة,SMS للمشترك,رسالة للمشترك','generator_owner','powerhub',1,now(),1,1),
('كيف أنشئ دورة رسالة مجدولة؟','كيف أرسل رسالة كل خميس أو بداية كل شهر؟','["رسالة دورية","رسالة مجدولة","كل خميس","بداية الشهر","دورة رسائل"]'::jsonb,'من نظام الرسائل اختر إنشاء دورة مجدولة، وحدد هل هي دورية متكررة أو غير دورية، ثم اختر الجدول مثل كل خميس أو يوم 2 من كل شهر، وحدد القالب والمستلمين. راجع المعاينة والجدول قبل التفعيل.','messaging','المراسلات','scheduled_message_cycle_create','published','رسالة دورية,رسالة مجدولة,كل خميس,بداية الشهر,دورة رسائل','generator_owner','powerhub',1,now(),1,1),
('كيف أضيف مستخدمًا أو أعدل صلاحياته؟','كيف أنشئ مستخدمًا وأعطيه صلاحية؟','["إضافة مستخدم","إنشاء مستخدم","تعديل الصلاحيات","صلاحيات المستخدم"]'::jsonb,'من إدارة المستخدمين اختر إنشاء المستخدم أو افتح مستخدمًا قائمًا للتعديل، ثم حدد نوع المستخدم والصلاحيات المتاحة واحفظ. الصلاحيات تعتمد على الدور والخطة وحالة الحساب، ولا يمكن للمساعد تنفيذ تغيير الصلاحيات نيابة عنك.','users','إدارة المستخدمين','user_create_update','published','إضافة مستخدم,إنشاء مستخدم,تعديل الصلاحيات,صلاحيات المستخدم','generator_owner','powerhub',1,now(),1,1),
('كيف أرقّي باقة أو أضيف إضافة؟','كيف أرقّي الخطة أو أضيف Add-on؟','["ترقية الباقة","ترقية الخطة","إضافة Add-on","إضافة خدمة"]'::jsonb,'من إدارة اشتراك صاحب المولد/طلبات الترقية راجع الباقات والإضافات المتاحة ثم اختر الترقية أو الإضافة المناسبة. الإضافات مستقلة عن تاريخ انتهاء الباقة الأساسية وفق قواعد الاشتراك المعتمدة، ويجب مراجعة السعر والمدة قبل التأكيد.','subscription','إدارة الاشتراك','subscription_upgrade_addon','published','ترقية الباقة,ترقية الخطة,إضافة Add-on,إضافة خدمة','generator_owner','powerhub',1,now(),1,1)
) as v(title,primary_question,alternative_questions,answer,category,linked_route,related_operation,status,search_aliases,audience,source,version,published_at,created_by_user_id,updated_by_user_id)
where not exists (select 1 from public.chat_knowledge_articles a where a.primary_question=v.primary_question);